def infer(kind='lifo',cap=99,policy='always'):
 S=np.zeros_like(X)
 for i,row in enumerate(X):
  st=[]
  for t,a in enumerate(row):
   S[i,t]=st[-1] if st else 0
   if a in (7,15):
    st.append(1 if a==15 else 2)
    if len(st)>cap:st=st[-cap:]
   elif a in (4,5) and st:
    want=1 if a==4 else 2
    if kind=='lifo':
     if policy=='always' or st[-1]==want:st.pop()
    elif kind=='fifo':
     if policy=='always' or st[0]==want:st.pop(0)
    elif kind=='clear':st=[]
    elif kind=='search':
     ix=[j for j,s in enumerate(st) if s==want]
     if ix: st.pop(ix[-1])
 return S
