source='''import numpy as np

def memory_features(X,cap=4,pm=.99,pw=.3,decay=.02,extra=.03,background=.1,overflow=0.):
 ns=2**(cap+1)-1;s=np.arange(1,ns+1);dep=np.floor(np.log2(s)).astype(int);top=np.where(s==1,0,np.where(s%2==0,1,2));I=np.eye(ns)
 def mat(d):
  a=np.zeros((ns,ns));a[np.arange(ns),np.asarray(d,dtype=int)-1]=1.;return a
 pop=mat(np.maximum(s//2,1));drop=mat(np.where(s>1,2**np.maximum(dep-1,0)+s%(2**np.maximum(dep-1,0)),1))
 age=(1-decay)*I+decay*drop
 M=np.repeat(I[None],16,axis=0)
 for a in (15,7):
  n=2*s+(a==7);n=np.where(n>=2**(cap+1),2**cap+n%(2**cap),n)
  M[a]=mat(n)
  if overflow:
   small=2**(cap-1)+n%(2**(cap-1));M[a]=(1-overflow)*M[a]+overflow*mat(np.where(dep>=cap-1,small,n))
 for a,k in [(4,1),(5,2)]:
  pr=np.where(top==k,pm,pw);popped=(1-extra)*pop+extra*(pop@pop)
  M[a]=age@(pr[:,None]*popped+(1-pr[:,None])*I)
 # Background loss is reduced on pushes and inert symbols; fresh top stays exact.
 slow=(1-decay*background)*I+decay*background*drop
 for a in range(16):
  if a not in (4,5):M[a]=slow@M[a]
 B=np.zeros((len(X),ns));B[:,0]=1.;W=np.zeros((*X.shape,3))
 for t in range(X.shape[1]):
  for k in range(3):W[:,t,k]=B[:,top==k].sum(1)
  a=X[:,t]
  for token in np.unique(a):
   ix=np.flatnonzero(a==token);B[ix]=B[ix]@M[token]
 return W
'''
